{"content": "1|/**
2| * Phase 4 client-local race maths: ampel light phases, the frozen-car start
3| * gate, ms-precise finish crossing and podium placement. PURE: no DOM, no
4| * timers, no RNG — time is injected (local ms), physics only borrowed.
5| * Counts toward the size budget — kept tight.
6| */
7|import { stepCar } from '../vehicle/carPhysics.js';
8|
9|/** How long before goAt the ampel shows red+amber (German sequence). */
10|export const AMBER_BEFORE_MS = 1000;
11|
12|/**
13| * ampelState(serverNow, goAt) → 'red' | 'red+amber' | 'green'.
14| * German sequence: solid red until the last AMBER_BEFORE_MS before the shared
15| * goAt, then red+amber, then green the instant serverNow reaches goAt.
16| */
17|export function ampelState(serverNow, goAt) {
18|  if (serverNow >= goAt) return 'green';
19|  if (serverNow >= goAt - AMBER_BEFORE_MS) return 'red+amber';
20|  return 'red';
21|}
22|
23|/**
24| * createStartGate({ isGreen, onJump }) → { step(car, input, spec, dt) }.
